from fractions import Fraction
import math

def can_reach_one(m, n, max_elements=200):
    s = {Fraction(m, n), Fraction(n, m)}
    visited = list(s)

    for _ in range(max_elements):
        new_numbers = set()
        for i in range(len(visited)):
            for j in range(i + 1, len(visited)):
                x = visited[i]
                y = visited[j]

                am = (x + y) / 2
                if am == 1: return True
                if am not in s:
                    new_numbers.add(am)

                hm = (2 * x * y) / (x + y)
                if hm == 1: return True
                if hm not in s:
                    new_numbers.add(hm)

        if not new_numbers:
            break

        for num in new_numbers:
            if num not in s:
                s.add(num)
                visited.append(num)

        if len(visited) > 500: # Limit the search space
            break

    return 1 in s

# Let's check some values of m+n.
for s_val in range(2, 25):
    found = False
    for m in range(1, s_val):
        n = s_val - m
        if math.gcd(m, n) == 1:
            if can_reach_one(m, n):
                print(f"m+n={s_val} is possible with m={m}, n={n}")
                found = True
                break
    if not found:
        print(f"m+n={s_val} is NOT possible")

