from fractions import Fraction
from collections import deque

def can_reach_one_bfs(m, n, max_sum=2000):
    start_numbers = {Fraction(m, n), Fraction(n, m)}
    queue = deque([tuple(sorted(list(start_numbers)))])
    visited = {tuple(sorted(list(start_numbers)))}

    while queue:
        current_numbers = queue.popleft()
        if Fraction(1, 1) in current_numbers:
            return True

        for i in range(len(current_numbers)):
            for j in range(i + 1, len(current_numbers)):
                x = current_numbers[i]
                y = current_numbers[j]

                z1 = (x + y) / 2
                if z1.numerator + z1.denominator <= max_sum:
                    new_numbers = tuple(sorted(list(set(current_numbers) | {z1})))
                    if new_numbers not in visited:
                        visited.add(new_numbers)
                        queue.append(new_numbers)

                z2 = (2 * x * y) / (x + y)
                if z2.numerator + z2.denominator <= max_sum:
                    new_numbers = tuple(sorted(list(set(current_numbers) | {z2})))
                    if new_numbers not in visited:
                        visited.add(new_numbers)
                        queue.append(new_numbers)
    return False

